// DowntimeSecondsGT applies the GT predicate on the "downtime_seconds" field.
func DowntimeSecondsGT(v int) predicate.MonitorStat {
	return predicate.MonitorStat(sql.FieldGT(FieldDowntimeSeconds, v))
}

// DowntimeSecondsGTE applies the GTE predicate on the "downtime_seconds" field.
func DowntimeSecondsGTE(v int) predicate.MonitorStat {
	return predicate.MonitorStat(sql.FieldGTE(FieldDowntimeSeconds, v))
}

// DowntimeSecondsLT applies the LT predicate on the "downtime_seconds" field.
func DowntimeSecondsLT(v int) predicate.MonitorStat {
	return predicate.MonitorStat(sql.FieldLT(FieldDowntimeSeconds, v))
}

// DowntimeSecondsLTE applies the LTE predicate on the "downtime_seconds" field.
func DowntimeSecondsLTE(v int) predicate.MonitorStat {
	return predicate.MonitorStat(sql.FieldLTE(FieldDowntimeSeconds, v))
}

// HasMonitor applies the HasEdge predicate on the "monitor" edge.
func HasMonitor() predicate.MonitorStat {
	return predicate.MonitorStat(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, MonitorTable, MonitorColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasMonitorWith applies the HasEdge predicate on the "monitor" edge with a given conditions (other predicates).
func HasMonitorWith(preds ...predicate.Monitor) predicate.MonitorStat {
	return predicate.MonitorStat(func(s *sql.Selector) {
		step := newMonitorStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MonitorStat) predicate.MonitorStat {
	return predicate.MonitorStat(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MonitorStat) predicate.MonitorStat {
	return predicate.MonitorStat(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MonitorStat) predicate.MonitorStat {
	return predicate.MonitorStat(sql.NotPredicates(p))
}
